ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS email text, ADD COLUMN IF NOT EXISTS photo_url text;
ALTER TABLE public.property_photos ADD COLUMN IF NOT EXISTS caption text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS storage_path text;
ALTER TABLE public.leads ADD COLUMN IF NOT EXISTS temperature text NOT NULL DEFAULT 'quente', ADD COLUMN IF NOT EXISTS transaction_type text NOT NULL DEFAULT 'comprar', ADD COLUMN IF NOT EXISTS loss_reason text, ADD COLUMN IF NOT EXISTS next_action text, ADD COLUMN IF NOT EXISTS next_action_date timestamptz, ADD COLUMN IF NOT EXISTS timeline jsonb NOT NULL DEFAULT '[]', ADD COLUMN IF NOT EXISTS property_title text, ADD COLUMN IF NOT EXISTS broker_name text, ADD COLUMN IF NOT EXISTS capture_data jsonb NOT NULL DEFAULT '{}';
CREATE TABLE public.broker_permissions (user_id uuid PRIMARY KEY, pode_cadastrar_imovel boolean NOT NULL DEFAULT false, pode_ver_ofertas_gerais boolean NOT NULL DEFAULT false, pode_ver_captacoes boolean NOT NULL DEFAULT false);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.broker_permissions TO authenticated;
GRANT ALL ON public.broker_permissions TO service_role;
ALTER TABLE public.broker_permissions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.agency_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), administrator_id uuid);
GRANT SELECT ON public.agency_settings TO authenticated;
GRANT ALL ON public.agency_settings TO service_role;
ALTER TABLE public.agency_settings ENABLE ROW LEVEL SECURITY;
UPDATE public.profiles p SET email = u.email FROM auth.users u WHERE u.id=p.id;
CREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.user_id=_user_id AND p.active) $$;
CREATE OR REPLACE FUNCTION public.is_staff_manager(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('owner','admin')) $$;
CREATE OR REPLACE FUNCTION public.can_view_all(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff_manager(_user_id) OR (public.is_staff(_user_id) AND EXISTS(SELECT 1 FROM public.broker_permissions WHERE user_id=_user_id AND pode_ver_ofertas_gerais)) $$;
CREATE OR REPLACE FUNCTION public.can_write_property(_user_id uuid, _broker_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff_manager(_user_id) OR (public.is_staff(_user_id) AND _broker_id=_user_id AND EXISTS(SELECT 1 FROM public.broker_permissions WHERE user_id=_user_id AND pode_cadastrar_imovel)) $$;
CREATE OR REPLACE FUNCTION public.is_hidden_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role='owner') $$;
CREATE POLICY "permission read" ON public.broker_permissions FOR SELECT TO authenticated USING (user_id=auth.uid() OR (public.is_staff_manager(auth.uid()) AND (NOT public.is_hidden_staff(user_id) OR public.has_role(auth.uid(),'owner'))));
CREATE POLICY "permission manage" ON public.broker_permissions FOR ALL TO authenticated USING (public.is_staff_manager(auth.uid()) AND NOT public.is_hidden_staff(user_id)) WITH CHECK(public.is_staff_manager(auth.uid()) AND NOT public.is_hidden_staff(user_id));
CREATE POLICY "agency staff read" ON public.agency_settings FOR SELECT TO authenticated USING(public.is_staff(auth.uid()));
DROP POLICY "own profile insert" ON public.profiles;
DROP POLICY "own profile read" ON public.profiles;
DROP POLICY "own profile update" ON public.profiles;
CREATE POLICY "team profiles read" ON public.profiles FOR SELECT TO authenticated USING(public.is_staff(auth.uid()) AND (NOT public.is_hidden_staff(id) OR public.has_role(auth.uid(),'owner')));
CREATE POLICY "managers profiles update" ON public.profiles FOR UPDATE TO authenticated USING(public.is_staff_manager(auth.uid()) AND (NOT public.is_hidden_staff(id) OR public.has_role(auth.uid(),'owner'))) WITH CHECK(public.is_staff_manager(auth.uid()) AND (NOT public.is_hidden_staff(id) OR public.has_role(auth.uid(),'owner')));
DROP POLICY "read own roles" ON public.user_roles;
CREATE POLICY "roles read" ON public.user_roles FOR SELECT TO authenticated USING(public.is_staff(auth.uid()) AND (user_id=auth.uid() OR (public.is_staff_manager(auth.uid()) AND (role<>'owner' OR public.has_role(auth.uid(),'owner')))));
DROP POLICY "public read published" ON public.properties;
DROP POLICY "staff insert" ON public.properties;
DROP POLICY "staff update" ON public.properties;
DROP POLICY "manager delete" ON public.properties;
CREATE POLICY "catalog published" ON public.properties FOR SELECT TO anon USING(status='publicado');
CREATE POLICY "staff property read" ON public.properties FOR SELECT TO authenticated USING((NOT public.is_staff(auth.uid()) AND status='publicado') OR public.can_view_all(auth.uid()) OR (public.is_staff(auth.uid()) AND broker_id=auth.uid()));
CREATE POLICY "property insert" ON public.properties FOR INSERT TO authenticated WITH CHECK(public.can_write_property(auth.uid(),broker_id) AND created_by=auth.uid());
CREATE POLICY "property update" ON public.properties FOR UPDATE TO authenticated USING(public.can_write_property(auth.uid(),broker_id)) WITH CHECK(public.can_write_property(auth.uid(),broker_id));
CREATE POLICY "property delete" ON public.properties FOR DELETE TO authenticated USING(public.can_write_property(auth.uid(),broker_id));
DROP POLICY "read photos" ON public.property_photos;
DROP POLICY "staff write photos" ON public.property_photos;
CREATE POLICY "visible photos" ON public.property_photos FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.properties p WHERE p.id=property_id));
CREATE POLICY "property photos manage" ON public.property_photos FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.properties p WHERE p.id=property_id AND public.can_write_property(auth.uid(),p.broker_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.properties p WHERE p.id=property_id AND public.can_write_property(auth.uid(),p.broker_id)));
DROP POLICY "staff read leads" ON public.leads;
DROP POLICY "staff update leads" ON public.leads;
DROP POLICY "manager delete leads" ON public.leads;
CREATE POLICY "lead staff read" ON public.leads FOR SELECT TO authenticated USING(public.can_view_all(auth.uid()) OR (public.is_staff(auth.uid()) AND broker_id=auth.uid()));
CREATE POLICY "lead staff update" ON public.leads FOR UPDATE TO authenticated USING(public.is_staff_manager(auth.uid()) OR (public.is_staff(auth.uid()) AND broker_id=auth.uid())) WITH CHECK(public.is_staff_manager(auth.uid()) OR (public.is_staff(auth.uid()) AND broker_id=auth.uid()));
CREATE POLICY "lead manager delete" ON public.leads FOR DELETE TO authenticated USING(public.is_staff_manager(auth.uid()));
CREATE OR REPLACE FUNCTION public.lead_before_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.property_id IS NOT NULL THEN SELECT broker_id,code,title INTO new.broker_id,new.property_code,new.property_title FROM public.properties WHERE id=new.property_id AND status='publicado'; IF NOT FOUND THEN RAISE EXCEPTION 'Imóvel indisponível'; END IF; ELSE SELECT administrator_id INTO new.broker_id FROM public.agency_settings WHERE id=true; END IF; IF EXISTS(SELECT 1 FROM public.leads WHERE phone=new.phone AND coalesce(property_id::text,'')=coalesce(new.property_id::text,'') AND created_at>now()-interval '10 minutes') THEN RAISE EXCEPTION 'duplicate_lead'; END IF; RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name,email) VALUES(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email),new.email); RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.retire_broker(_broker_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; pc int; lc int; BEGIN IF NOT public.is_staff_manager(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF; SELECT administrator_id INTO target FROM public.agency_settings WHERE id=true; IF target IS NULL OR target=_broker_id OR public.is_hidden_staff(_broker_id) THEN RAISE EXCEPTION 'Administrador principal não pode ser excluído'; END IF; UPDATE public.properties SET broker_id=target,created_by=CASE WHEN created_by=_broker_id THEN target ELSE created_by END WHERE broker_id=_broker_id OR created_by=_broker_id; GET DIAGNOSTICS pc=ROW_COUNT; UPDATE public.leads SET broker_id=target WHERE broker_id=_broker_id; GET DIAGNOSTICS lc=ROW_COUNT; UPDATE public.profiles SET active=false WHERE id=_broker_id; DELETE FROM public.user_roles WHERE user_id=_broker_id; DELETE FROM public.broker_permissions WHERE user_id=_broker_id; RETURN jsonb_build_object('reassignedProps',pc,'reassignedLeads',lc,'reassignedMsgs',lc); END $$;
REVOKE ALL ON FUNCTION public.retire_broker(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.retire_broker(uuid) TO authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.properties,public.property_photos,public.profiles,public.leads TO authenticated;
GRANT SELECT ON public.properties,public.property_photos TO anon;
GRANT INSERT ON public.leads TO anon;
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.properties,public.property_photos,public.profiles,public.leads,public.user_roles TO service_role;
CREATE POLICY "property image read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='property-images' AND EXISTS(SELECT 1 FROM public.properties p WHERE p.id::text=(storage.foldername(name))[1]));
CREATE POLICY "property image upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='property-images' AND EXISTS(SELECT 1 FROM public.properties p WHERE p.id::text=(storage.foldername(name))[1] AND public.can_write_property(auth.uid(),p.broker_id)));
CREATE POLICY "property image delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='property-images' AND EXISTS(SELECT 1 FROM public.properties p WHERE p.id::text=(storage.foldername(name))[1] AND public.can_write_property(auth.uid(),p.broker_id)));
CREATE POLICY "capture managers read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='captacoes' AND public.is_staff_manager(auth.uid()));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['properties','property_photos','profiles','leads','user_roles','broker_permissions'] LOOP IF NOT EXISTS(SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename=t) THEN EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I',t); END IF; END LOOP; END $$;